head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDFIS00400_08.xml";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
scwin.vArray = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_ContgntDebt.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 우발채무  조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(pan_Ctnt);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.contgntDebtAE" + "&outputMessageId=FIS_CONTGNT_DEBT" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vAcntclsDt;
    dts_ContgntDebt.DataID = encodeURI(url);
    dts_ContgntDebt.Reset();
};


/**
 * 컨텐츠 append
 */
scwin.fn_AppendContents = function() {
    var strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:575px;font-family:돋움체;'>";
    for (var nRow = 1; nRow <= dts_ContgntDebt.getTotalRow(); nRow++) {
        strContent = strContent + dts_ContgntDebt.getCellData(nRow, "CTNT");
    }
    strContent = strContent + "</div>";
    pan_Ctnt.innerHTML = strContent;
    $c.cm.CloseWin(dts_ContgntDebt.getTotalRow(), pan_Ctnt);
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_ContgntDebt_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_EmpStat);
    $c.stf.alert_error(dts_ContgntDebt);
};
scwin.dts_ContgntDebt_OnLoadCompleted = function(rowcount) {
    if (dts_ContgntDebt.errorMsg) {
        $c.win.alert(dts_ContgntDebt.errorMsg);
    }

    // 멀티Row의 데이터를 하나로 합치자.
    scwin.fn_AppendContents();
};
